// Pattern: x_<vendor-or-company-prefix>_<short-app-name>
x_acme_fleet     // Fleet Management
x_acme_vms       // Visitor Management

// Avoid generic names:
x_acme_app1      // means nothing 6 months from now

// Renaming x_acme_fleet after creation would require
// renaming every real artifact that already exists:
x_acme_fleet_vehicle          // every table
current.x_acme_fleet_vehicle  // every field reference
new x_acme_fleet.SomeClass()  // every Script Include call
